create table if not exists public.marketplace_organizations (organization_id uuid primary key default gen_random_uuid(), legal_name text, display_name text not null, status text not null default 'active' check (status in ('active','suspended','closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.marketplace_memberships (membership_id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.marketplace_organizations(organization_id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check (role in ('owner','admin','buyer','seller','moderator','operator')), status text not null default 'active' check (status in ('active','suspended','revoked')), created_at timestamptz not null default now(), unique (organization_id,user_id,role));
create table if not exists public.marketplace_identity_verifications (verification_id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, organization_id uuid references public.marketplace_organizations(organization_id) on delete cascade, verification_type text not null, status text not null check (status in ('pending','verified','expired','revoked')), evidence_ref text, policy_version text not null, verified_at timestamptz, expires_at timestamptz, created_at timestamptz not null default now(), check (user_id is not null or organization_id is not null));
alter table public.marketplace_listings add column if not exists organization_id uuid references public.marketplace_organizations(organization_id);
alter table public.marketplace_listings add column if not exists state_version bigint not null default 1;
alter table public.marketplace_listings add column if not exists state_updated_at timestamptz not null default now();
alter table public.marketplace_listings add column if not exists state_updated_by uuid;
alter table public.marketplace_orders add column if not exists buyer_organization_id uuid references public.marketplace_organizations(organization_id);
alter table public.marketplace_orders add column if not exists seller_organization_id uuid references public.marketplace_organizations(organization_id);
alter table public.marketplace_orders add column if not exists order_state text not null default 'payment_pending' check (order_state in ('payment_pending','paid','fulfillment','complete','refund_requested','refunded','dispute'));
alter table public.marketplace_orders add column if not exists state_version bigint not null default 1;
alter table public.marketplace_orders add column if not exists state_updated_at timestamptz not null default now();
alter table public.marketplace_orders add column if not exists state_updated_by uuid;
alter table public.marketplace_orders add column if not exists idempotency_key text;
alter table public.marketplace_orders add column if not exists checkout_session_id text;
create unique index if not exists marketplace_orders_idempotency_key_uq on public.marketplace_orders(idempotency_key) where idempotency_key is not null;
create unique index if not exists marketplace_orders_checkout_session_uq on public.marketplace_orders(checkout_session_id) where checkout_session_id is not null;
create table if not exists public.marketplace_listing_state_events (event_id uuid primary key default gen_random_uuid(), listing_id uuid not null references public.marketplace_listings(id) on delete cascade, from_state text, to_state text not null check (to_state in ('draft','review','published','rejected')), state_version bigint not null, actor_user_id uuid, actor_organization_id uuid, reason text, created_at timestamptz not null default now(), unique (listing_id,state_version));
create table if not exists public.marketplace_order_state_events (event_id uuid primary key default gen_random_uuid(), order_id uuid not null references public.marketplace_orders(id) on delete cascade, from_state text, to_state text not null check (to_state in ('payment_pending','paid','fulfillment','complete','refund_requested','refunded','dispute')), state_version bigint not null, actor_user_id uuid, actor_organization_id uuid, idempotency_key text, reason text, created_at timestamptz not null default now(), unique (order_id,state_version));
create index if not exists marketplace_listings_state_idx on public.marketplace_listings(status,state_version,state_updated_at);
create index if not exists marketplace_orders_state_idx on public.marketplace_orders(order_state,state_version,created_at);

create or replace function public.transition_marketplace_listing(p_listing_id uuid,p_expected_version bigint,p_to_state text,p_actor_user_id uuid,p_actor_org_id uuid default null,p_reason text default null) returns public.marketplace_listings language plpgsql security definer set search_path='' as $$ declare r public.marketplace_listings; old_state text; new_version bigint; begin if p_to_state not in ('draft','review','published','rejected') then raise exception 'invalid listing state'; end if; select status,state_version into old_state,new_version from public.marketplace_listings where id=p_listing_id for update; if not found then raise exception 'listing not found'; end if; if new_version <> p_expected_version then raise exception 'stale listing version'; end if; if p_actor_org_id is not null and not exists (select 1 from public.marketplace_memberships m where m.organization_id=(select l.organization_id from public.marketplace_listings l where l.id=p_listing_id) and m.organization_id=p_actor_org_id and m.user_id=p_actor_user_id and m.status='active' and m.role in ('owner','admin','seller','moderator','operator')) then raise exception 'actor not authorized for listing organization'; end if; update public.marketplace_listings set status=p_to_state,state_version=state_version+1,state_updated_at=now(),state_updated_by=p_actor_user_id where id=p_listing_id returning * into r; insert into public.marketplace_listing_state_events(listing_id,from_state,to_state,state_version,actor_user_id,actor_organization_id,reason) values(p_listing_id,old_state,p_to_state,r.state_version,p_actor_user_id,p_actor_org_id,p_reason); return r; end; $$;
create or replace function public.transition_marketplace_order(p_order_id uuid,p_expected_version bigint,p_to_state text,p_actor_user_id uuid,p_actor_org_id uuid default null,p_idempotency_key text default null,p_reason text default null) returns public.marketplace_orders language plpgsql security definer set search_path='' as $$ declare r public.marketplace_orders; old_state text; new_version bigint; begin if p_to_state not in ('payment_pending','paid','fulfillment','complete','refund_requested','refunded','dispute') then raise exception 'invalid order state'; end if; select order_state,state_version into old_state,new_version from public.marketplace_orders where id=p_order_id for update; if not found then raise exception 'order not found'; end if; if new_version <> p_expected_version then raise exception 'stale order version'; end if; if p_actor_org_id is not null and not exists (select 1 from public.marketplace_memberships m where m.organization_id=p_actor_org_id and m.user_id=p_actor_user_id and m.status='active' and m.role in ('owner','admin','buyer','seller','moderator','operator')) then raise exception 'actor not authorized for order organization'; end if; update public.marketplace_orders set order_state=p_to_state,state_version=state_version+1,state_updated_at=now(),state_updated_by=p_actor_user_id where id=p_order_id returning * into r; insert into public.marketplace_order_state_events(order_id,from_state,to_state,state_version,actor_user_id,actor_organization_id,idempotency_key,reason) values(p_order_id,old_state,p_to_state,r.state_version,p_actor_user_id,p_actor_org_id,p_idempotency_key,p_reason); return r; end; $$;
revoke execute on function public.transition_marketplace_listing(uuid,bigint,text,uuid,uuid,text) from public,anon;
revoke execute on function public.transition_marketplace_order(uuid,bigint,text,uuid,uuid,text,text) from public,anon;
grant execute on function public.transition_marketplace_listing(uuid,bigint,text,uuid,uuid,text) to authenticated,service_role;
grant execute on function public.transition_marketplace_order(uuid,bigint,text,uuid,uuid,text,text) to authenticated,service_role;
alter table public.marketplace_organizations enable row level security;
alter table public.marketplace_memberships enable row level security;
alter table public.marketplace_identity_verifications enable row level security;
alter table public.marketplace_listings enable row level security;
alter table public.marketplace_orders enable row level security;
